import { Alert, Badge, Button, Group, Loader, Progress, SegmentedControl, Select, Stack, Text, TextInput } from "@mantine/core";
import { useWidgetAction, useWidgetHost, useWidgetOptions, useWidgetQuery, useWidgetServices, useWidgetState } from "@homarr/widget-sdk";
import type { Connection, Overview, SonarrOptions } from "./types";
export default function Sonarr() {
  const host = useWidgetHost(); const services = useWidgetServices(); const options = useWidgetOptions<SonarrOptions>();
  const [tab,setTab] = useWidgetState("tab","calendar");
  const [source,setSource] = useWidgetState("source","all");
  const [filter,setFilter] = useWidgetState("filter","");
  const query = useWidgetQuery<Overview>("overview",{}, {refetchInterval:60000});
  const search = useWidgetAction<{id:number;status:string},{connection:Connection;episodeIds:number[]}>("searchEpisodes");
  const label = (connection:Connection) => sources.find((source) => source.connection === connection)?.label ?? connection;
  const sources = query.data?.sources ?? [];
  const rows = sources.filter((entry) => source === "all" || source === entry.connection).flatMap((entry) => {
    let items = entry.calendar;
    if (tab === "missing") items = entry.missing.items;
    if (tab === "queue") items = entry.queue.items;
    return items.map((item,index) => ({...item,connection:entry.connection,rowKey:`${entry.connection}:${tab}:${item.id ?? index}`}));
  }).filter((item) => `${item.title} ${item.subTitle ?? item.seriesTitle ?? ""}`.toLowerCase().includes(filter.toLowerCase()));
  const visible = host.displayMode === "advanced" ? rows : rows.slice(0,4);
  const requestSearch = async (connection:Connection,id:number,title:string) => {
    if (await services.confirm({title:"Search for this episode?",message:`Ask ${label(connection)} to find and download an eligible release for ${title}?`})) search.mutate({connection,episodeIds:[id]});
  };
  return <Stack h="100%" p="md" gap="sm" style={{overflow:"auto"}}>
    <Group justify="space-between"><Text fw={600}>{options.title}</Text><Badge>{sources.reduce((sum,entry) => sum+entry.queue.totalCount,0)} queued</Badge></Group>
    <SegmentedControl value={tab} onChange={setTab} data={[{label:"Upcoming",value:"calendar"},{label:"Missing",value:"missing"},{label:"Queue",value:"queue"}]} />
    {sources.length > 1 && <Select aria-label="Sonarr server" value={source} onChange={(value) => setSource(value ?? "all")} data={[{value:"all",label:"All servers"},...sources.map((entry) => ({value:entry.connection,label:label(entry.connection)}))]} />}
    {host.displayMode === "advanced" && <TextInput aria-label="Filter episodes" placeholder="Filter series or episode…" value={filter} onChange={(event) => setFilter(event.currentTarget.value)} />}
    {query.isPending && <Loader size="sm" />}
    {query.error && <Alert color="red">{query.error.message}</Alert>}
    {sources.filter((entry) => entry.error).map((entry) => <Alert key={entry.connection} color="red" title={label(entry.connection)}>{entry.error}</Alert>)}
    {search.error && <Alert color="red">{search.error.message}</Alert>}
    {search.data?.id && <Text size="xs" c="teal">Search command {search.data.id}: {search.data.status}. Sonarr will select an eligible release.</Text>}
    {visible.map((item) => <Stack key={item.rowKey} gap={4}><Group justify="space-between"><Text fw={500} size="sm">{item.subTitle ?? item.seriesTitle ?? item.title}</Text><Badge size="xs" variant="light">{label(item.connection)}</Badge></Group><Text size="xs" c="dimmed">{item.title}{item.seasonNumber !== undefined && ` · S${item.seasonNumber} E${item.episodeNumber ?? "?"}`}</Text>{item.startDate && <Text size="xs">{new Date(item.startDate).toLocaleString(host.locale)}</Text>}{item.percentComplete !== undefined && <Progress value={item.percentComplete} aria-label={`${item.title} download progress`} />}<Group gap="xs">{(item.link || item.links?.[0]?.href) && <Button size="compact-xs" variant="subtle" onClick={() => services.navigate(item.link ?? item.links?.[0]?.href ?? "")}>Open in Sonarr</Button>}{tab === "missing" && typeof item.id === "number" && <Button size="compact-xs" disabled={host.isEditMode || search.isPending} onClick={() => void requestSearch(item.connection,item.id!,item.title)}>Search episode</Button>}</Group></Stack>)}
    {query.data && !rows.length && <Text c="dimmed">No episodes match this view.</Text>}
    <Group><Button size="xs" variant="light" onClick={() => void query.refetch()}>Refresh</Button>{host.displayMode === "compact" && <Button size="xs" variant="subtle" onClick={services.openAdvanced}>All episodes and filters</Button>}</Group>
  </Stack>;
}

