import type { EpisodeRow, SearchInput, SonarrOptions } from "./types";
import { callWidgetIntegration, defineWidgetServer, getWidgetConnectionGroup, getWidgetServerContext } from "@homarr/widget-sdk/server";
export default defineWidgetServer({
  overview: async (_input, context) => {
    const {options} = await getWidgetServerContext<SonarrOptions>(context);
    const start = new Date();
    const end = new Date(start.getTime()+Math.max(1,Math.min(90,Number(options.days)||7))*86400000);
    const names = await getWidgetConnectionGroup(context, "sonarr");
    if (!names.length) throw new Error("Bind at least one Sonarr integration");
    const sources = await Promise.all(names.map(async ({connection,label}) => {
      const call = <T,>(capability:string,input:unknown) => callWidgetIntegration<T>(context,{connection,capability,input});
      try {
        const [calendar,missing,queue] = await Promise.all([
          call<EpisodeRow[]>("sonarr.calendar",{start:start.toISOString(),end:end.toISOString()}),
          call<{items:EpisodeRow[];totalCount:number}>("sonarr.missing",{limit:100}), call<{items:EpisodeRow[];totalCount:number}>("sonarr.queue",{limit:100}),
        ]);
        return {connection,label,calendar,missing,queue};
      } catch (error) { return {connection,label,calendar:[],missing:{items:[],totalCount:0},queue:{items:[],totalCount:0},error:error instanceof Error ? error.message : String(error)}; }
    }));
    return {sources};
  },
  searchEpisodes: async (input:SearchInput,context) => {
    const connections = await getWidgetConnectionGroup(context, "sonarr");
    if (!connections.some(({connection}) => connection === input?.connection) || !Array.isArray(input?.episodeIds) || !input.episodeIds.length || input.episodeIds.length > 100 || input.episodeIds.some((id) => !Number.isInteger(id) || id < 1)) throw new Error("Choose valid episode IDs from a declared Sonarr server");
    return callWidgetIntegration(context,{connection:input.connection,capability:"sonarr.searchEpisodes",input:{episodeIds:input.episodeIds}});
  },
});

